def parse_args(argv):
    if not argv:
        return {"command": "list"}
    name, rest = argv[0], argv[1:]
    if name == "add":
        return {"command": "add", "title": " ".join(rest)}
    if name == "done":
        return {"command": "done", "id": int(rest[0])}
    if name in ("list", "save"):
        return {"command": name}
    return {"command": "unknown", "name": name}


def add_task(tasks, title):
    next_id = max([t["id"] for t in tasks], default=0) + 1
    return list(tasks) + [{"id": next_id, "title": title, "done": False}]


def complete_task(tasks, task_id):
    out = []
    for t in tasks:
        done = True if t["id"] == task_id else t["done"]
        out.append({"id": t["id"], "title": t["title"], "done": done})
    return out


def format_task_list(tasks):
    if not tasks:
        return "No tasks."
    lines = []
    for t in tasks:
        box = "x" if t["done"] else " "
        lines.append("[%s] %d %s" % (box, t["id"], t["title"]))
    return "\n".join(lines)


def serialise(tasks):
    parts = []
    for t in tasks:
        parts.append("%d|%s|%s" % (t["id"], "done" if t["done"] else "open", t["title"]))
    return "\n".join(parts)


def parse(text):
    tasks = []
    for line in text.split("\n"):
        if not line.strip():
            continue
        raw_id, state, title = line.split("|", 2)
        tasks.append({"id": int(raw_id), "title": title, "done": state == "done"})
    return tasks


def find_task(tasks, task_id):
    for t in tasks:
        if t["id"] == task_id:
            return t
    return None


def run(tasks, command):
    name = command["command"]
    if name == "add":
        updated = add_task(tasks, command["title"])
        fresh = updated[-1]
        return updated, "Added task %d: %s" % (fresh["id"], fresh["title"])
    if name == "done":
        target = find_task(tasks, command["id"])
        if target is None:
            return tasks, "No task with id %d" % command["id"]
        return (complete_task(tasks, command["id"]),
                "Completed task %d: %s" % (target["id"], target["title"]))
    if name == "list":
        return tasks, format_task_list(tasks)
    if name == "save":
        return tasks, serialise(tasks)
    return tasks, "Unknown command: %s" % command["name"]
